@classmethod
def _verify_generation_evidence(
    cls, generation_dir: str, manifest: dict[str, Any]
) -> tuple[
    str | None, dict[str, Any] | None, str, dict[str, str | None]
]:
    """Verify a structurally accepted generation's data files, log
    binding and terminal replay.

    Reads both data files read-only and records their digests even
    when one is absent, then applies the definitive ordering:
    checkpoint presence and digest, journal presence and digest,
    content validation, journal-to-checkpoint binding, and an actual
    replay of every frame. Returns ``(None, evidence, "ok", files)``
    on success or ``(reason, None, replay, files)`` naming the first
    defect; ``replay`` is the terminal-replay conclusion (``"ok"``,
    ``"not-run"`` when an earlier check stopped replay, or the replay
    failure message). Missing files are defects; other read failures
    raise :class:`OSError`.
    """
    files: dict[str, str | None] = {
        "checkpoint": None,
        "journal": None,
    }
    checkpoint_path = os.path.join(
        generation_dir, cls._GENERATION_CHECKPOINT
    )
    journal_path = os.path.join(
        generation_dir, cls._GENERATION_JOURNAL
    )
    try:
        with open(checkpoint_path, "rb") as handle:
            checkpoint_bytes = handle.read()
    except FileNotFoundError:
        checkpoint_bytes = None
    if checkpoint_bytes is not None:
        files["checkpoint"] = hashlib.sha256(
            checkpoint_bytes
        ).hexdigest()
    try:
        with open(journal_path, "rb") as handle:
            journal_bytes = handle.read()
    except FileNotFoundError:
        journal_bytes = None
    if journal_bytes is not None:
        files["journal"] = hashlib.sha256(journal_bytes).hexdigest()

    if checkpoint_bytes is None:
        return "checkpoint file is missing", None, "not-run", files

